  const matrix = new Matrix([[1, 2], [3, 4]]);
  assert.strictEqual(matrix.get(0, 0), 1);
  assert.strictEqual(matrix.get(0, 1), 2);
  assert.strictEqual(matrix.get(1, 0), 3);
