class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = defaultdict(list)

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        self.edges[a].append((b, weight))
        self.edges[b].append((a, weight))

    def nodes(self):
        return self.nodes

    def neighbors(self, a):
        return sorted(self.edges[a], key=lambda x: x[0])

    def bfs(self, start):
        if start not in self.nodes:
            raise KeyError(f"Node {start} not in graph")

        visited = set()
        queue = deque([start])
        result = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor, _ in self.neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)

        return result
