    parts = line.split()
    if len(parts) != 10:
        raise ValueError("Invalid log line format")
    
    ip = parts[0]
    time = parts[3][1:-1]
    request = parts[5][1:-1]
    method, path = request.split()
    status = int(parts[8])
    bytes_str = parts[9]
