class Matrix {
constructor(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error("No rows provided");
  }

  const numCols = rows[0].length;
  if (numCols === 0) {
    throw new Error("Empty rows provided");
  }

  for (const row of rows) {
    if (!Array.isArray(row) || row.length !== numCols) {
      throw new Error("Rows of different lengths or not arrays");
    }
    for (const value of row) {
      if (typeof value !== 'number' || !isFinite(value)) {
        throw new Error("Non-finite number in matrix");
      }
    }
  }

  this.rows = rows;
}

  shape() {
    // shape implementation will go here
  }

  get(r, c) {
    // get implementation will go here
  }

  toArray() {
    // toArray implementation will go here
  }

  mul(x) {
    if (typeof x === 'number') {
      // Scalar multiplication
      return new Matrix(this.rows.map(row => row.map(value => value * x)));
    } else if (x instanceof Matrix) {
      // Matrix product
      const [rowsA, colsA] = this.shape();
      const [rowsB, colsB] = x.shape();
      if (colsA !== rowsB) {
        throw new Error("Inner dimensions do not match for matrix multiplication");
      }
      const result = [];
      for (let i = 0; i < rowsA; i++) {
        const newRow = [];
        for (let j = 0; j < colsB; j++) {
          let sum = 0;
          for (let k = 0; k < colsA; k++) {
            sum += this.get(i, k) * x.get(k, j);
          }
          newRow.push(sum);
        }
        result.push(newRow);
      }
      return new Matrix(result);
    } else {
      throw new Error("Invalid argument type for mul");
    }
  }
}

module.exports = Matrix;

