    if (this.cache.has(key)) {
      this.usageOrder.set(key, Date.now());
      return this.cache.get(key);
    }
    return undefined;
  }

  has(key) {
    return this.cache.has(key);
  }

  size() {
    return this.cache.size;
  }

  keys() {
    return Array.from(this.usageOrder.keys()).reverse();
