class Library {
  constructor() {
    this.books = {};
    this.members = {};
    this.holds = {};
  }

  addBook(isbn, copies) {
    if (!this.books[isbn]) {
      this.books[isbn] = { copies: copies, available: copies };
    } else {
      this.books[isbn].copies += copies;
      this.books[isbn].available += copies;
    }
  }

