        const newRow = [];
        for (let j = 0; j < colsB; j++) {
          let sum = 0;
          for (let k = 0; k < colsA; k++) {
            sum += this.get(i, k) * x.get(k, j);
          }
          newRow.push(sum);
        }
        result.push(newRow);
      }
      return new Matrix(result);
